sys_script_fix.script:
var eventId = 'EVT0001017'; // Replace with your actual Event sys_id

var vendorGR = new GlideRecord('x_1790229_event_ma_vendor'); // Replace with your vendor table name
vendorGR.addQuery('u_event_id.number', eventId); // Assuming 'u_event' is the reference field to the Event
vendorGR.query();

while (vendorGR.next()) {
    gs.info('Vendor Name: ' + vendorGR.getDisplayValue('u_vendor_name')); // Adjust field name if different
    gs.info('Email: ' + vendorGR.getValue('u_email'));             // Adjust accordingly
    gs.info('Phone: ' + vendorGR.getValue('u_contact_number'));

}
